// === Config : 4 structures avec tokens depuis env vars n8n ===
// Les tokens Pennylane sont injectes via les variables d'environnement
// du conteneur n8n (Coolify > Service > Environment Variables).
// Constitution I (Secrets-First) : pas de secret en dur dans le code.

const structures = [
  { code: 'HMA',     token: $env.PENNYLANE_TOKEN_HMA },
  { code: 'STIVMAT', token: $env.PENNYLANE_TOKEN_STIVMAT },
  { code: 'STA',     token: $env.PENNYLANE_TOKEN_STA },
  { code: 'ETPA',    token: $env.PENNYLANE_TOKEN_ETPA }
];

return structures.map(s => ({ json: s }));

// === Fetch Pennylane + Mapping FEC + Hash MD5 ===
// Pagination complete, retry avec backoff, mapping colonnes FEC

const items = $input.all();
const entiteId = items[0].json.entite_id;
const exerciceId = items[0].json.exercice_id;
const fecImportId = items[0].json.fec_import_id;
const structureCode = items[0].json.code;

// Token Pennylane passe depuis le noeud Config via la boucle
// On le recupere depuis l'item original dans le contexte de la boucle
const loopItem = $('Config 4 structures').first();
const token = loopItem.json.token;

if (!token) {
  throw new Error(`Token Pennylane manquant pour ${structureCode}. Verifier les env vars PENNYLANE_TOKEN_${structureCode} dans Coolify.`);
}

const baseUrl = 'https://app.pennylane.com/api/external/v2/ledger_entries';
const perPage = 100;
let page = 1;
let totalPages = 1;
let allEntries = [];
let retryCount = 0;
const maxRetries = 3;

while (page <= totalPages) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: `${baseUrl}?page=${page}&per_page=${perPage}`,
      headers: {
        'Authorization': `Bearer ${token}`,
        'Accept': 'application/json'
      }
    });

    totalPages = response.pagination.pages;

    for (const entry of response.ledger_entries) {
      const compteNum = entry.planitem.auxiliary_code
        ? entry.planitem.number + entry.planitem.auxiliary_code
        : entry.planitem.number;

      // Fingerprint MD5 de deduplication (non-cryptographique)
      const hashInput = `${entiteId}${entry.journal.code}${entry.document_number}${entry.date}${compteNum}${entry.debit}${entry.credit}`;
      const crypto = require('crypto');
      const hashMd5 = crypto.createHash('md5').update(hashInput).digest('hex');

      allEntries.push({
        entite_id: entiteId,
        exercice_id: exerciceId,
        fec_import_id: fecImportId,
        journal_code: entry.journal.code,
        journal_lib: entry.journal.label,
        ecriture_num: entry.document_number,
        ecriture_date: entry.date,
        compte_num: compteNum,
        compte_lib: entry.planitem.label,
        comp_aux_num: entry.planitem.auxiliary_code || null,
        comp_aux_lib: entry.planitem.auxiliary_label || null,
        piece_ref: entry.document_number,
        piece_date: entry.date,
        ecriture_lib: entry.label,
        debit: entry.debit || 0,
        credit: entry.credit || 0,
        ecriture_let: entry.lettering_code || null,
        date_let: entry.lettering_date || null,
        valid_date: entry.validated_at || null,
        montant_devise: null,
        idevise: null,
        pcg_numero: null,
        hash_md5: hashMd5
      });
    }

    page++;
    retryCount = 0;

  } catch (error) {
    // Retry avec backoff exponentiel sur 429 (rate limit) et 500
    if (error.statusCode === 429 || error.statusCode === 500) {
      retryCount++;
      if (retryCount > maxRetries) {
        throw new Error(`Abandon apres ${maxRetries} retries sur ${error.statusCode} pour ${structureCode}`);
      }
      const waitMs = Math.pow(2, retryCount) * 1000;
      await new Promise(resolve => setTimeout(resolve, waitMs));
      continue;
    }
    if (error.statusCode === 401) {
      throw new Error(`Token invalide/expire pour ${structureCode}. Verifier PENNYLANE_TOKEN_${structureCode} dans Coolify.`);
    }
    throw error;
  }
}

// Retourner par batch de 500 pour l'INSERT
const batchSize = 500;
const batches = [];
for (let i = 0; i < allEntries.length; i += batchSize) {
  batches.push({
    entries: allEntries.slice(i, i + batchSize),
    nb_lignes_brut: allEntries.length,
    fec_import_id: fecImportId,
    entite_id: entiteId,
    exercice_id: exerciceId,
    code: structureCode
  });
}

return batches.map(b => ({ json: b }));

