={{ (() => {
  const entries = $json.entries;
  if (!entries || entries.length === 0) return 'SELECT 1;';
  const cols = Object.keys(entries[0]);
  const values = entries.map(e => 
    '(' + cols.map(c => {
      const v = e[c];
      if (v === null || v === undefined) return 'NULL';
      if (typeof v === 'number') return v;
      return "'" + String(v).replace(/'/g, "''") + "'";
    }).join(',') + ')'
  ).join(',
');
  return `INSERT INTO _staging_fec (${cols.join(',')}) VALUES
${values};

-- Upsert idempotent staging -> fec_ecriture
INSERT INTO fec_ecriture (
  entite_id, exercice_id, fec_import_id,
  journal_code, journal_lib, ecriture_num, ecriture_date,
  compte_num, compte_lib, comp_aux_num, comp_aux_lib,
  piece_ref, piece_date, ecriture_lib,
  debit, credit, ecriture_let, date_let, valid_date,
  montant_devise, idevise, pcg_numero, hash_md5
)
SELECT
  entite_id, exercice_id, fec_import_id,
  journal_code, journal_lib, ecriture_num, ecriture_date,
  compte_num, compte_lib, comp_aux_num, comp_aux_lib,
  piece_ref, piece_date, ecriture_lib,
  debit, credit, ecriture_let, date_let, valid_date,
  montant_devise, idevise, pcg_numero, hash_md5
FROM _staging_fec
ON CONFLICT (hash_md5) DO NOTHING;

-- Resoudre pcg_numero
UPDATE fec_ecriture
SET pcg_numero = resolve_compte(compte_num)
WHERE pcg_numero IS NULL AND entite_id = '${$json.entite_id}';

-- MAJ stats fec_import
UPDATE fec_import
SET
  nb_lignes_brut = ${$json.nb_lignes_brut},
  nb_lignes_inserees = (SELECT COUNT(*) FROM fec_ecriture WHERE fec_import_id = '${$json.fec_import_id}'),
  duree_secondes = EXTRACT(EPOCH FROM (now() - date_import)),
  statut = 'termine'
WHERE id = '${$json.fec_import_id}';`;
})() }}
